L27_1.m_CharStrID = "SOLDIER_NPC_NULL_NULL"
L27_1.m_Pos = "C"
L27_1.m_Talk_KOREA = "상황을 타개하는 데 도움을 드릴 수 있다면서요."
L27_1.m_fTalkTime = 0.03
L27_1.m_Talk_JPN = "現状を打開するのに役立つはずだと言っています。"
L27_1.m_Talk_ENG = "They say they've got something that could pull us out of this rut."
