L30_1 = {}
L30_1.m_CutScenKey_Talk = "OMEN_LOTUS_PROLOGUE@21#Talk"
L30_1.m_CutScenProcessKey = 0
L30_1.m_CutScenID = 7800101
L30_1.m_CutScenStrID = "OMEN_LOTUS_PROLOGUE"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "AIDE_NPC_NULL_NULL"
L30_1.m_Pos = "C"
L30_1.m_Talk_KOREA = "그 왜, 연합군 전략 회의에 애들 장난감 같은 거 들고 나왔다던 놈들 아닙니까."
L30_1.m_fTalkTime = 0.03
L30_1.m_Talk_JPN = "えっと、確か……連合軍の戦略会議に、子供のオモチャのようなものを持ち込んだやつらです。"
L30_1.m_Talk_ENG = "You know, the nerds who brought those fancy toys at the combined forces' strategy meeting."
L30_1.m_Talk_TWN = "就是那些在聯軍戰略會議像小孩一樣拿著玩具出現的傢伙吧？"
L30_1.m_Talk_DEU = "You know, the nerds who brought those fancy toys at the combined forces' strategy meeting."
L30_1.m_Talk_FRA = "You know, the nerds who brought those fancy toys at the combined forces' strategy meeting."
L31_1 = {}
L31_1.m_CutScenKey_Talk = "OMEN_LOTUS_PROLOGUE@22#Talk"
L31_1.m_CutScenProcessKey = 0
