L31_1.m_Crash = 40
L31_1.m_Talk_KOREA = "그런데 너 어디 소속이야?"
L31_1.m_fTalkTime = 0.03
L31_1.m_Talk_JPN = "お前、どこの所属だ？"
L31_1.m_Talk_ENG = "By the way, what's your unit, trooper?"
L31_1.m_Talk_TWN = "但你是哪個單位的？"
L31_1.m_Talk_DEU = "By the way, what's your unit, trooper?"
L31_1.m_Talk_FRA = "By the way, what's your unit, trooper?"
L32_1 = {}
L32_1.m_CutScenKey_Talk = "OMEN_LOTUS_PROLOGUE@23#Talk"
L32_1.m_CutScenProcessKey = 0
L32_1.m_CutScenID = 7800101
L32_1.m_CutScenStrID = "OMEN_LOTUS_PROLOGUE"
