L32_1.m_CharStrID = "AIDE_NPC_NULL_NULL"
L32_1.m_Pos = "C"
L32_1.m_Crash = 30
L32_1.m_Talk_KOREA = "지금이 어떤 상황인데 그런 작자들이 진지에 들락거려! 통제 똑바로 안 해!"
L32_1.m_fTalkTime = 0.03
L32_1.m_Talk_JPN = "こんな状況で、やつらが陣地に入っていいわけないだろ！　何を考えてるんだ！"
L32_1.m_Talk_ENG = "How could you let some outsiders like that go in and out of our positions in a situation like this?! Keep your security in check!"
L32_1.m_Talk_TWN = "現在這種情況還讓那種人進出營地！還不好好把關！"
L32_1.m_Talk_DEU = "How could you let some outsiders like that go in and out of our positions in a situation like this?! Keep your security in check!"
L32_1.m_Talk_FRA = "How could you let some outsiders like that go in and out of our positions in a situation like this?! Keep your security in check!"
