L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L42_1.m_Talk_KOREA = "그날, 보호 구역 안에 있던 모두가 숨을 죽였다."
L42_1.m_fTalkTime = 0.03
L42_1.m_bTalkCenterFadeIn = true
L42_1.m_Talk_JPN = "あの日、保護区域にいたみんなが、息を潜めた。"
L42_1.m_Talk_ENG = "That day, everyone inside the protected zone held their breath."
L42_1.m_Talk_TWN = "那一天，保護區內的所有人都屏住呼吸。"
L42_1.m_Talk_DEU = "That day, everyone inside the protected zone held their breath."
L42_1.m_Talk_FRA = "That day, everyone inside the protected zone held their breath."
L43_1 = {}
