L43_1.m_CutScenProcessKey = 0
L43_1.m_CutScenID = 7800101
L43_1.m_CutScenStrID = "OMEN_LOTUS_PROLOGUE"
L43_1.m_bWaitClick = true
L43_1.m_fWaitTime = 0
L43_1.m_Talk_KOREA = "이제는 기억조차 희미한 어린 날의 기억이지만,"
L43_1.m_fTalkTime = 0.03
L43_1.m_bTalkCenterFadeIn = true
L43_1.m_Talk_JPN = "今ではうっすらとしか思い出せない、幼かった頃の記憶だけど。"
L43_1.m_Talk_ENG = "The memories are hazy now, just a child's blur."
L43_1.m_Talk_TWN = "雖然現在對我來說已經是模糊到幾乎想不起來的童年記憶，"
L43_1.m_Talk_DEU = "The memories are hazy now, just a child's blur."
L43_1.m_Talk_FRA = "The memories are hazy now, just a child's blur."
