L40_1.m_CharStrID = L41_1
L41_1 = "대균열에 빛이 번쩍일 때마다 좋은 일이 일어난 적은 없는 거, 알지?"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "大亀裂が光り出した時にいいことがあったためしはない。知ってるでしょ？"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Nothing good ever follows when the Grand Dimension Crevice flashes. You know that."
