L49_1 = "<color=#ffd34c>현 시간부로 최고 등급 재난 경보가 발령되었습니다.</color>"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "<color=#ffd34c>現時刻をもって最高ランクの災難警報が発令されました。</color>"
L48_1.m_Talk_JPN = L49_1
L49_1 = "<color=#ffd34c>As of now, the highest-level disaster alert has been issued.</color>"
L48_1.m_Talk_ENG = L49_1
L49_1 = "<color=#ffd34c>即刻起發布最高等級災難警報。</color>"
L48_1.m_Talk_TWN = L49_1
L49_1 = "<color=#ffd34c>As of now, the highest-level disaster alert has been issued.</color>"
