L49_1.m_CutScenStrID = "OMEN_LOTUS_PROLOGUE"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L50_1 = "<color=#ffd34c>모든 시민분들은 관리국 요원들의 지시에 따라 대피하십시오.</color>"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "<color=#ffd34c>市民の皆様は、管理局員の指示に従い避難してください。</color>"
L49_1.m_Talk_JPN = L50_1
L50_1 = "<color=#ffd34c>All citizens, evacuate according to the instructions of Administration personnel.</color>"
L49_1.m_Talk_ENG = L50_1
L50_1 = "<color=#ffd34c>所有市民請依照管理局人員指示撤離。</color>"
L49_1.m_Talk_TWN = L50_1
L50_1 = "<color=#ffd34c>All citizens, evacuate according to the instructions of Administration personnel.</color>"
L49_1.m_Talk_DEU = L50_1
L50_1 = "<color=#ffd34c>All citizens, evacuate according to the instructions of Administration personnel.</color>"
L49_1.m_Talk_FRA = L50_1
