L50_1.m_CutScenStrID = "OMEN_LOTUS_PROLOGUE"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L51_1 = "<color=#ffd34c>이상, 안내된 지침은 재난경보 해제까지 유효합니다.</color>"
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "<color=#ffd34c>以上、ご案内している行動指針は災難警報が解除されるまで有効です。</color>"
L50_1.m_Talk_JPN = L51_1
L51_1 = "<color=#ffd34c>The broadcast guidelines will remain in effect until the disaster alert is lifted.</color>"
